class Solution {
    public String nearestPalindromic(String n) {
        int L = n.length();
        long orig = Long.parseLong(n);
        Set<Long> cands = new HashSet<>();
        cands.add((long) Math.pow(10, L - 1) - 1);
        cands.add((long) Math.pow(10, L) + 1);

        long prefix = Long.parseLong(n.substring(0, (L + 1) / 2));
        for (long p : new long[]{prefix - 1, prefix, prefix + 1}) {
            String s = Long.toString(p);
            StringBuilder sb = new StringBuilder(s);
            if (L % 2 != 0) sb.deleteCharAt(sb.length() - 1);
            cands.add(Long.parseLong(s + sb.reverse().toString()));
        }
        cands.remove(orig);

        long best = -1;
        for (long c : cands) {
            if (best == -1 || Math.abs(c - orig) < Math.abs(best - orig) || (Math.abs(c - orig) == Math.abs(best - orig) && c < best)) {
                best = c;
            }
        }
        return String.valueOf(best);
    }
}

var nearestPalindromic = function(n) {
    const L = n.length;
    const orig = BigInt(n);
    const cands = new Set();
    cands.add(BigInt(10 ** (L - 1) - 1));
    cands.add(BigInt(10 ** L + 1));

    const prefix = BigInt(n.slice(0, Math.floor((L + 1) / 2)));
    for (const p of [prefix - 1n, prefix, prefix + 1n]) {
        const s = p.toString();
        let rev = s.split("").reverse().join("");
        if (L % 2 !== 0) {
            rev = s.slice(0, -1).split("").reverse().join("");
        }
        cands.add(BigInt(s + rev));
    }
    cands.delete(orig);

    let best = null;
    for (const c of cands) {
        const diff = c > orig ? c - orig : orig - c;
        if (best === null) {
            best = c;
        } else {
            const bestDiff = best > orig ? best - orig : orig - best;
            if (diff < bestDiff || (diff === bestDiff && c < best)) {
                best = c;
            }
        }
    }
    return best.toString();
};
